import ajvModule from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

export interface SchemaValidationError {
  readonly keyword: string;
  readonly instancePath?: string;
  readonly dataPath?: string;
  readonly params: Record<string, unknown>;
  readonly message?: string;
}

export interface SchemaValidator {
  (input: Record<string, unknown>): boolean | PromiseLike<unknown>;
  readonly errors?: SchemaValidationError[] | null;
}

export interface SchemaCompiler {
  compile(schema: Record<string, unknown>): SchemaValidator;
}

interface AjvConstructor {
  new (options: Record<string, unknown>): SchemaCompiler;
  readonly prototype?: object;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: SchemaValidator;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = createSchemaCompiler(ajvModule);
  private readonly schemaValidators = new WeakMap<object, SchemaValidator>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validator =
      typeof definition === 'function' ? undefined : compileToolSchema(this.ajv, resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Returns a rejection ToolResponse on schema failure; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validator =
      tool.validator ??
      resolveCachedValidator(this.ajv, this.schemaValidators, name, this.resolveDefinition(tool.definitionSource));
    const rejection = validateToolInput(name, validator, input);
    if (rejection) return rejection;
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

export function createSchemaCompiler(rawModule: unknown): SchemaCompiler {
  const unwrapped = isObjectRecord(rawModule) && 'default' in rawModule ? rawModule.default : rawModule;
  if (!isAjvConstructor(unwrapped)) {
    throw new Error('Unable to initialize Ajv validator');
  }
  const options = supportsVocabularies(unwrapped.prototype)
    ? {strict: false, validateFormats: false, allErrors: true}
    : {format: false, unknownFormats: 'ignore', jsonPointers: true, allErrors: true};
  return new unwrapped(options);
}

function isAjvConstructor(candidate: unknown): candidate is AjvConstructor {
  return typeof candidate === 'function';
}

function supportsVocabularies(proto: unknown): boolean {
  return isObjectRecord(proto) && 'addVocabulary' in proto;
}

function isObjectRecord(candidate: unknown): boolean & (typeof candidate extends Record<string, unknown> ? true : boolean) {
  return typeof candidate === 'object' && candidate !== null;
}

function resolveCachedValidator(
  ajv: SchemaCompiler,
  cache: WeakMap<object, SchemaValidator>,
  toolName: string,
  definition: ToolDefinition
): SchemaValidator {
  const cached = cache.get(definition.inputSchema);
  if (cached) return cached;
  const compiled = compileToolSchema(ajv, toolName, definition.inputSchema);
  cache.set(definition.inputSchema, compiled);
  return compiled;
}

function compileToolSchema(ajv: SchemaCompiler, toolName: string, schema: Record<string, unknown>): SchemaValidator {
  try {
    return ajv.compile(schema);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${reason}`, {cause: error});
  }
}

function validateToolInput(
  toolName: string,
  validator: SchemaValidator,
  input: Record<string, unknown>
): ToolResponse | undefined {
  if (validator(input)) return undefined;
  const failures = (validator.errors ?? []).map(formatValidationError);
  log.warn('tool', 'input validation failed', {name: toolName, failures});
  return {result: `Invalid input for tool "${toolName}": ${failures.join('; ')}`};
}

export function formatValidationError(error: SchemaValidationError): string {
  const path = validationFieldPath(error);
  const constraint = validationConstraint(error);
  return path ? `${path}: ${constraint}` : constraint;
}

function validationFieldPath(error: SchemaValidationError): string {
  const rawPath = error.instancePath ?? error.dataPath ?? '';
  const trimmedPath = rawPath.replace(/^[/.]/, '');
  const basePath = trimmedPath.replace(/\//g, '.');
  const child = readChildProperty(error.params);
  if (!child) return basePath;
  return basePath ? `${basePath}.${child}` : child;
}

function readChildProperty(params: Record<string, unknown>): string | undefined {
  const child = params.missingProperty ?? params.additionalProperty;
  return typeof child === 'string' ? child : undefined;
}

function validationConstraint(error: SchemaValidationError): string {
  const baseMessage = error.message ?? `failed "${error.keyword}" constraint`;
  const {allowedValues} = error.params;
  if (error.keyword === 'enum' && Array.isArray(allowedValues)) {
    const labels = allowedValues.map(entry => String(entry));
    return `${baseMessage} (${labels.join(', ')})`;
  }
  return baseMessage;
}

